// ❌ Problem: Culture-specific hardcoding
function displayDate(date) {
  return `${date.getMonth()+1}/${date.getDate()}/${date.getFullYear()}`;
  // Only works for US format
}

// ✅ Solution: Internationalized approach
function displayDate(date, locale) {
  return date.toLocaleDateString(locale, {
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });
  // Works for any locale: '15. März 2024' (de-DE), 
  // '2024年3月15日' (ja-JP), '15 March 2024' (en-GB)
}

